import { SCENARIOS, SECTIONS, CANVAS_BLOCKS, emptyCanvas, forecast, metrics, progress, newPlan, snapshot, validatePlan, demoPlans } from './model.js';

const icons = {
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',
 chart:'<path d="M3 3v18h18M7 15l5-6 4 3 5-8"/>',
 layers:'<path d="m12 3 10 5-10 5L2 8Z"/><path d="m2 12 10 5 10-5M2 16l10 5 10-5"/>',
 history:'<path d="M3 11a9 9 0 1 1 2.6 7.4M3 4v7h7M12 7v5l3 2"/>',
 settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m10 3-1 3-3 1-3 3v4l3 1 1 3 3 3h4l1-3 3-1 3-3v-4l-3-1-1-3-3-3Z"/>',
 plus:'<path d="M12 5v14M5 12h14"/>', arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>', chevron:'<path d="m9 5 7 7-7 7"/>', down:'<path d="m6 9 6 6 6-6"/>', check:'<path d="m5 12 4 4L19 6"/>', search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>', close:'<path d="m6 6 12 12M6 18 18 6"/>', download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>', upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>', sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>', sprout:'<path d="M12 21V11M12 15C4 15 3 8 3 8s9-2 9 7ZM12 11c0-8 8-8 8-8s2 8-8 8Z"/>', trend:'<path d="m3 17 6-6 4 4 8-10M15 5h6v6"/>', wallet:'<path d="M20 8V5H5a2 2 0 0 1 0-4h13v4M3 3v16a2 2 0 0 0 2 2h15V8H5M16 12h5v5h-5Z"/>', people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 5a6 6 0 0 1 3 6"/>', folder:'<path d="M3 6a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>', help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3v2M12 17h.01"/>', edit:'<path d="m16 3 5 5-12 12-6 1 1-6ZM14 5l5 5"/>', menu:'<path d="M4 6h16M4 12h16M4 18h16"/>', leaf:'<path d="M20 3C9 1 2 7 5 15s17 5 15-12ZM5 20 16 9"/>'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.file}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app');
let planView=localStorage.getItem('forma-plan-view')||'canvas', canvasExpanded=false;
let plans=[], activeId=localStorage.getItem('forma-active'), user=localStorage.getItem('forma-user')||'Mehdi', view='overview', scenario='realistic', section='summary', source='browser', search='', filter='all', saveQueue=Promise.resolve(), editingTimer, toastTimer;
const active=()=>plans.find(p=>p.id===activeId)||plans[0];
const money=(n,compact=false)=>new Intl.NumberFormat('en-US',{style:'currency',currency:active()?.currency||'USD',maximumFractionDigits:0,...(compact?{notation:'compact',maximumFractionDigits:1}:{})}).format(n);
const date=s=>new Date(s).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const time=s=>new Date(s).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
const toast=msg=>{const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3600);};
function persist(plan=active()) {
  localStorage.setItem('forma-plans',JSON.stringify(plans));
  if(source!=='files'||!plan) return Promise.resolve(true);
  const copy=structuredClone(plan);
  setSaveState('Saving…');
  saveQueue=saveQueue.catch(()=>false).then(async()=>{
    try {const r=await fetch('/api/plans/'+encodeURIComponent(copy.id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(copy)});if(!r.ok)throw Error();setSaveState('All changes saved');return true;}
    catch {setSaveState('Saved in browser · file save failed');toast('File save failed. Your browser copy is safe; export a backup.');return false;}
  }); return saveQueue;
}
function setSaveState(text){const el=document.querySelector('#save-state');if(el)el.textContent=text;}
function touch(){active().updatedAt=new Date().toISOString();setSaveState('Saving…');clearTimeout(editingTimer);editingTimer=setTimeout(()=>persist(),400);}
function flush(){clearTimeout(editingTimer);return persist();}
function navButton(id,label,i){return `<button class="nav-item ${view===id?'active':''}" data-view="${id}">${icon(i)}<span>${label}</span>${id==='versions'?`<span class="nav-count">${active()?.versions.length||0}</span>`:''}</button>`;}
function render(){
  const p=active();
  document.body.classList.toggle('canvas-expanded',view==='canvas'&&canvasExpanded);
  app.innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-view="overview"><span class="brand-mark">${icon('layers')}</span>forma<span class="brand-dot">®</span></a><div class="workspace-tag"><span class="workspace-avatar">S</span><span>Studio workspace<small>A space for what’s next</small></span><span class="tiny-dot"></span></div><div class="nav-label">WORKSPACE</div><nav>${navButton('overview','Overview','grid')}${navButton('plans','Business plans','file')}${navButton('canvas','Business canvas','grid')}${navButton('scenarios','Scenario planning','layers')}${navButton('financials','Financial forecast','chart')}${navButton('versions','Version history','history')}</nav><div class="sidebar-lower"><div class="sidebar-note"><span class="note-spark">✳</span><h4>Big ideas start small.</h4><p>A little clarity today.<br>A stronger business tomorrow.</p><button data-action="guide">A little guidance ${icon('arrow')}</button></div>${navButton('settings','Workspace settings','settings')}<button class="profile" data-action="profile"><span class="avatar">${esc(user.slice(0,1).toUpperCase())}</span><span>${esc(user)}<small>Your personal workspace</small></span>${icon('down')}</button></div></aside>
  <div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu icon-button" aria-label="Open navigation" data-action="menu">${icon('menu')}</button><span>Workspace</span>${icon('chevron')}<strong>${view==='editor'?'Business plans':({overview:'Overview',plans:'Business plans',scenarios:'Scenario planning',financials:'Financial forecast',versions:'Version history',canvas:'Business canvas',settings:'Settings'}[view])}</strong></div><div class="topbar-right"><span class="save-indicator"><span></span><span id="save-state">${source==='files'?'All changes saved':'Saved in this browser'}</span></span><button class="icon-button help-button" aria-label="Help" data-action="guide">${icon('help')}</button><span class="avatar small">${esc(user.slice(0,1).toUpperCase())}</span></div></header><main class="${view==='canvas'?'canvas-page':''}">${({overview:overview,plans:plansView,editor:editor,canvas:canvasView,scenarios:scenarioView,financials:financials,versions:versionsView,settings:settingsView}[view]||overview)()}</main><footer><span>Made for the way you build.</span><span><span class="tiny-dot"></span> ${source==='files'?'Local files connected':'Private browser storage'} <span class="footer-divider">/</span> Forma workspace</span></footer></div>`;
  if(p){localStorage.setItem('forma-active',p.id);}bind();
  app.querySelectorAll('[data-canvas-block]').forEach(growCanvasInput);
}
function planViewTabs(){return `<div class="plan-view-bar"><div class="segmented plan-view-tabs" aria-label="Business plan view"><button class="${view==='canvas'?'selected':''}" data-view="canvas" aria-pressed="${view==='canvas'}">${icon('grid')} Canvas view</button><button class="${view==='editor'?'selected':''}" data-view="editor" aria-pressed="${view==='editor'}">${icon('file')} Written plan</button></div><p class="plan-view-note">Two views of your business. Both saved in the same plan.</p></div>`;}
function growCanvasInput(el){el.style.height='auto';el.style.height=Math.max(140,el.scrollHeight+2)+'px';}
function canvasView(){
  const p=active();if(!p)return noPlan();
  const canvas=p.canvas||emptyCanvas();
  const count=CANVAS_BLOCKS.filter(([id])=>canvas[id].trim()).length;
  return heading('YOUR BUSINESS, ON ONE CANVAS',esc(p.title),'Map the big picture. Click into any block and start writing.',`${planSelect()}<button class="button" data-action="export">${icon('download')} Export plan</button><button class="button primary" data-action="save-version">${icon('plus')} Save version</button>`)+planViewTabs()+`
    <div class="canvas-toolbar"><div><span class="canvas-label"><span class="tiny-dot"></span> Business Model Canvas</span><span class="canvas-help" id="canvas-completion">${count} of 9 blocks started</span></div><div><button class="button" data-action="print-canvas">${icon('file')} Print / PDF</button><button class="button" data-action="expand-canvas" aria-pressed="${canvasExpanded}">${icon(canvasExpanded?'close':'grid')} ${canvasExpanded?'Exit expanded view':'Expand canvas'}</button></div></div>
    <div class="canvas-scroll" tabindex="0" role="region" aria-label="Business Model Canvas. Scroll horizontally to see all nine blocks."><div class="business-canvas">${CANVAS_BLOCKS.map(([id,title,prompt,placeholder,i])=>`<section class="canvas-cell ${id}" aria-labelledby="canvas-heading-${id}"><div class="canvas-cell-heading"><h2 id="canvas-heading-${id}">${title}</h2>${icon(i)}</div><p class="canvas-cell-prompt" id="canvas-prompt-${id}">${prompt}</p><label class="sr-only" for="canvas-${id}">${title}</label><textarea id="canvas-${id}" data-canvas-block="${id}" aria-describedby="canvas-prompt-${id}" placeholder="${esc(placeholder)}" spellcheck="true">${esc(canvas[id])}</textarea><div class="canvas-cell-print">${esc(canvas[id])}</div></section>`).join('')}</div></div>
    <div class="canvas-footer"><span>Use short notes or bullet points. Every block autosaves. Scroll sideways on smaller screens.</span><span>Business Model Canvas by <a href="https://www.strategyzer.com/library/the-business-model-canvas" target="_blank" rel="noopener noreferrer">Strategyzer</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 3.0</a></span></div>`;
}
function canvasSnapshot(p){const c=p.canvas;if(!c||!CANVAS_BLOCKS.some(([id])=>c[id]?.trim()))return '';return `<h3>Business Model Canvas</h3><div class="snapshot-canvas">${CANVAS_BLOCKS.map(([id,title])=>`<div><h4>${title}</h4><p>${esc(c[id]||'Not written yet.')}</p></div>`).join('')}</div>`;}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function planSelect(){return `<select class="plan-select" id="plan-select" aria-label="Active business plan">${plans.map(p=>`<option value="${esc(p.id)}" ${active()?.id===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select>`;}
function noPlan(){return `<div class="empty-state">${icon('sprout')}<h2>A fresh start for your next idea.</h2><p>Create a business plan to explore its possibilities.</p><button class="button primary" data-action="new">${icon('plus')} Create a business plan</button></div>`;}
function overview(){const p=active();if(!p)return heading('YOUR WORKSPACE','Room for your next big idea.','Let’s give it a plan.')+noPlan();const m=metrics(p);return heading('A LITTLE STRUCTURE. A LOT OF POSSIBILITY.','A clearer plan forward<span class="olive">.</span>','Shape your ideas, explore the possibilities, and build with confidence.',`<button class="button primary" data-action="new">${icon('plus')} New business plan</button>`)+`
  <div class="overview-grid"><section class="hero-card"><div class="hero-content"><div class="pill"><span></span> YOUR NEXT CHAPTER</div><h2>Good businesses<br>start with a <em>plan.</em></h2><p>Bring your vision into focus. One thoughtful<br class="desktop-break"> decision at a time.</p><button class="button dark" data-action="continue">Continue your plan ${icon('arrow')}</button><div class="hero-footnote"><span class="mini-avatars"><b>M</b><b>P</b></span><span>A shared space. Your own possibilities.</span></div></div><div class="hero-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-stem"></div><div class="art-leaf leaf-one"></div><div class="art-leaf leaf-two"></div><div class="art-leaf leaf-three"></div><div class="art-leaf leaf-four"></div><div class="art-leaf leaf-five"></div><div class="art-pot"></div><span class="art-spark spark-one">✳</span><span class="art-spark spark-two">✧</span><span class="art-caption">ideas, taking shape.</span></div></section>
  <section class="workspace-summary panel"><div class="panel-heading"><h3>Your workspace, at a glance</h3>${icon('grid')}</div><div class="summary-stat"><span class="stat-icon sage">${icon('file')}</span><div><strong>${plans.length.toString().padStart(2,'0')}</strong><span>Business plans</span></div><span class="soft-label">${plans.filter(x=>x.owner===user).length} yours</span></div><div class="summary-stat"><span class="stat-icon sand">${icon('layers')}</span><div><strong>03</strong><span>Perspectives per plan</span></div><div class="three-dots"><b></b><b></b><b></b></div></div><div class="summary-stat"><span class="stat-icon blue">${icon('history')}</span><div><strong>${plans.reduce((n,x)=>n+x.versions.length,0).toString().padStart(2,'0')}</strong><span>Saved versions</span></div><span class="summary-caption">Every step counts</span></div><div class="summary-bottom">${icon('check')} Your ideas have a home here.</div></section></div>
  <section class="plans-section"><div class="section-heading"><div><h2>Your business plans <span class="count">${plans.length}</span></h2><p>Big ambitions, with a place to begin.</p></div><button class="text-button" data-view="plans">View all plans ${icon('arrow')}</button></div><div class="plan-cards">${plans.slice(0,2).map(planCard).join('')}<button class="new-plan-card" data-action="new"><span class="new-circle">${icon('plus')}</span><strong>A new idea in mind?</strong><span>Give it a little structure.</span><b>Create a plan ${icon('arrow')}</b></button></div></section>
  <section class="scenario-section"><div class="section-heading"><div><h2>One plan. Three possibilities.</h2><p>A little perspective makes for better decisions.</p></div><span class="context-label">${esc(p.title)} <span>·</span> 12-month outlook</span></div><div class="scenario-cards">${SCENARIOS.map(s=>scenarioCard(p,s,true)).join('')}</div></section>
  <section class="bottom-insight"><span class="insight-mark">${icon('sprout')}</span><p><strong>Progress over perfection.</strong> Your plan is a living document. Make a start, learn something, and come back to it.</p><button class="text-button" data-view="versions">See your journey ${icon('arrow')}</button></section>`;}
function planCard(p){const pct=progress(p);return `<article class="plan-card"><div class="plan-card-top"><span class="plan-logo ${p.industry==='Food & beverage'?'sand':'sage'}">${icon(p.industry==='Food & beverage'?'sun':'leaf')}</span><span class="status ${p.status==='Draft'?'draft':''}"><b></b>${esc(p.status)}</span><button class="icon-button" data-action="plan-options" data-id="${p.id}" aria-label="Options for ${esc(p.title)}">•••</button></div><button class="plan-title" data-action="open-plan" data-id="${p.id}">${esc(p.title)}</button><p class="plan-description">${esc(p.description||'A new idea, taking shape.')}</p><div class="plan-owner"><span class="avatar micro ${p.owner!==user?'partner':''}">${esc(p.owner.slice(0,1))}</span>${p.owner===user?'You':esc(p.owner)}<span class="owner-dot">·</span>${esc(p.industry)}</div><div class="progress-label"><span>Plan completeness</span><strong>${pct}%</strong></div><div class="progress-track"><div style="width:${pct}%"></div></div><div class="plan-card-footer"><span>Updated ${date(p.updatedAt)}</span><button class="text-button" data-action="open-plan" data-id="${p.id}">Open plan ${icon('arrow')}</button></div></article>`;}
function scenarioCard(p,s,preview=false){const m=metrics(p,s.id);return `<${preview?'button':'article'} class="scenario-card ${s.id}" ${preview?`data-action="scenario" data-id="${s.id}"`:''}><div class="scenario-card-top"><span class="scenario-icon">${icon(s.id==='optimistic'?'trend':s.id==='realistic'?'sprout':'sun')}</span><h3>${s.name}</h3>${s.id==='realistic'?'<span class="base-tag">BASE CASE</span>':icon('arrow')}</div><p>${s.description}</p><div class="scenario-value"><strong>${money(m.revenue,true)}</strong><span>projected revenue</span><svg viewBox="0 0 115 35" aria-hidden="true"><path d="${s.id==='optimistic'?'M2 33 18 27 30 28 44 19 57 20 73 11 86 13 111 2':s.id==='realistic'?'M2 32 18 28 30 29 44 23 57 25 73 17 86 18 111 9':'M2 28 18 25 30 27 44 21 57 24 73 20 86 23 111 15'}" fill="none" stroke="currentColor" stroke-width="2"/></svg></div></${preview?'button':'article'}>`;}
function plansView(){const filtered=plans.filter(p=>(filter==='all'||p.owner===user)&&`${p.title} ${p.description} ${p.owner}`.toLowerCase().includes(search.toLowerCase()));return heading('YOUR IDEAS, TAKING SHAPE','Business plans<span class="olive">.</span>','A home for every idea worth exploring.',`<button class="button" data-action="import">${icon('upload')} Import plan</button><button class="button primary" data-action="new">${icon('plus')} New business plan</button>`)+`<div class="list-toolbar"><div class="segmented"><button class="${filter==='all'?'selected':''}" data-filter="all">All plans <span>${plans.length}</span></button><button class="${filter==='mine'?'selected':''}" data-filter="mine">My plans</button></div><label class="search-box">${icon('search')}<input id="search" placeholder="Find a business plan…" value="${esc(search)}" aria-label="Search plans"></label></div><div class="plan-cards all-plans">${filtered.map(planCard).join('')}${filtered.length===0?'<p class="muted">No plans match your search.</p>':''}<button class="new-plan-card" data-action="new"><span class="new-circle">${icon('plus')}</span><strong>The next big thing.</strong><span>Start with a blank canvas.</span></button></div>`;}
function editor(){const p=active();if(!p)return noPlan();const current=SECTIONS.find(([id])=>id===section)||SECTIONS[0];return heading('BUILD SOMETHING YOU BELIEVE IN',esc(p.title),esc(p.description),`${planSelect()}<button class="button" data-action="export">${icon('download')} Export</button><button class="button primary" data-action="save-version">${icon('plus')} Save version</button>`)+planViewTabs()+`<div class="editor-grid"><aside class="section-list panel"><div class="section-list-heading">YOUR BUSINESS PLAN <span>${progress(p)}%</span></div><div class="progress-track"><div style="width:${progress(p)}%"></div></div>${SECTIONS.map(([id,name],i)=>`<button class="section-link ${section===id?'selected':''}" data-section="${id}"><span class="section-number ${p.sections[id].trim()?'done':''}">${p.sections[id].trim()?icon('check'):String(i+1).padStart(2,'0')}</span>${name}${icon('chevron')}</button>`).join('')}<button class="section-link" data-view="financials"><span class="section-number">${icon('chart')}</span>Financial forecast${icon('chevron')}</button></aside><section class="editor-paper panel"><div class="editor-eyebrow">SECTION ${SECTIONS.findIndex(([id])=>id===section)+1} OF 7 <span>Autosaved as you write</span></div><h2>${current[1]}</h2><p class="editor-subtitle">${current[2]}</p><div class="writing-prompt">${icon('sprout')}<p>${current[3]}</p></div><label class="sr-only" for="section-text">${current[1]}</label><textarea id="section-text" placeholder="Your ideas belong here. Start writing…">${esc(p.sections[section])}</textarea><div class="editor-bottom"><span id="word-count">${p.sections[section].trim().split(/\s+/).filter(Boolean).length} words</span><button class="text-button" data-action="next-section">Next section ${icon('arrow')}</button></div></section></div>`;}
function chart(p){const rows=SCENARIOS.map(s=>({s,rows:forecast(p,s.id)}));const max=Math.max(1,...rows.flatMap(({rows})=>rows.map(r=>r.revenue)));const paths=rows.map(({s,rows})=>`<path d="${rows.map((r,i)=>`${i?'L':'M'}${62+i*62.7} ${220-r.revenue/max*190}`).join(' ')}" stroke="${s.color}" stroke-width="3" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`).join('');return `<svg class="forecast-chart" viewBox="0 0 800 270" role="img" aria-label="Monthly revenue projection for all three scenarios. The table below includes exact values.">${[0,1,2,3,4].map(i=>`<line x1="60" y1="${30+i*47.5}" x2="755" y2="${30+i*47.5}" stroke="#e9ece5" stroke-dasharray="4 4"/><text x="48" y="${34+i*47.5}" text-anchor="end">${esc(money(max*(1-i/4),true))}</text>`).join('')}${paths}${Array.from({length:12},(_,i)=>`<text x="${62+i*62.7}" y="252" text-anchor="middle">M${i+1}</text>`).join('')}</svg>`;}
function numberField(label,key,value,suffix='',min=0,max=1e12){return `<label class="field"><span>${label}</span><div class="input-affix"><input type="number" data-assumption="${key}" value="${value}" min="${min}" max="${max}" step="any" required><span>${suffix}</span></div></label>`;}
function financials(){const p=active();if(!p)return noPlan();const m=metrics(p,scenario);const rows=forecast(p,scenario);return heading('LET THE NUMBERS TELL A STORY','Financial forecast<span class="olive">.</span>','See how your assumptions shape the year ahead.',`${planSelect()}<button class="button" data-action="csv">${icon('download')} Export CSV</button>`)+`<div class="financial-layout"><section class="panel assumptions"><div class="panel-heading"><h3>The starting point</h3>${icon('settings')}</div><p class="muted">Shared across your three scenarios.</p><form id="assumptions-form">${numberField('Initial monthly revenue','monthlyRevenue',p.assumptions.monthlyRevenue,p.currency)}${numberField('Monthly fixed costs','fixedCosts',p.assumptions.fixedCosts,p.currency)}${numberField('Variable costs (% of revenue)','variableCosts',p.assumptions.variableCosts,'%',0,100)}${numberField('Starting cash','startingCash',p.assumptions.startingCash,p.currency)}<button class="button primary full-width" type="submit">Update forecast ${icon('arrow')}</button></form><p class="field-hint">Month 1 is your first operating month. Fixed costs remain constant; revenue compounds monthly.</p></section><div><div class="segmented scenario-toggle">${SCENARIOS.map(s=>`<button class="${scenario===s.id?'selected':''}" data-scenario="${s.id}"><span class="color-dot" style="background:${s.color}"></span>${s.name}</button>`).join('')}</div><div class="metric-grid"><div class="metric panel"><span>Annual revenue</span><strong>${money(m.revenue,true)}</strong><small>12-month projection</small></div><div class="metric panel"><span>Operating profit</span><strong class="${m.profit<0?'negative':'olive'}">${money(m.profit,true)}</strong><small>${m.margin.toFixed(1)}% operating margin</small></div><div class="metric panel"><span>Ending cash</span><strong class="${m.endingCash<0?'negative':''}">${money(m.endingCash,true)}</strong><small>${m.runway<0?'Cash stays positive':`Cash runs out in month ${m.runway+1}`}</small></div></div><section class="panel chart-panel"><div class="panel-heading"><h3>Revenue, in perspective</h3><span class="muted">12 months · ${p.currency}</span></div><div class="chart-legend">${SCENARIOS.map(s=>`<span><b style="background:${s.color}"></b>${s.name}</span>`).join('')}</div>${chart(p)}</section></div></div><section class="panel table-panel"><div class="panel-heading"><h3>Your ${scenario} forecast</h3><span class="muted">Operating break-even: ${m.breakEven<0?'beyond month 12':`month ${m.breakEven+1}`}</span></div><div class="table-scroll"><table><thead><tr><th>Month</th><th>Revenue</th><th>Total costs</th><th>Operating profit</th><th>Cash balance</th></tr></thead><tbody>${rows.map(r=>`<tr><td>Month ${r.month+1}</td><td>${money(r.revenue)}</td><td>${money(r.cost)}</td><td class="${r.profit<0?'negative':'olive'}">${money(r.profit)}</td><td>${money(r.cash)}</td></tr>`).join('')}</tbody></table></div></section><p class="footnote">Planning estimates before taxes, financing, depreciation, and capital expenditure. Adjust assumptions as you learn.</p>`;}
function scenarioView(){const p=active();if(!p)return noPlan();return heading('PLAN FOR WHAT COULD BE','Three paths. One vision<span class="olive">.</span>','Explore the upside, prepare for challenges, and find your likely path.',planSelect())+`<div class="scenario-cards detailed">${SCENARIOS.map(s=>scenarioCard(p,s)).join('')}</div><section class="panel scenario-assumptions"><div class="panel-heading"><h3>Make the possibilities your own</h3><span class="muted">${esc(p.title)}</span></div><p class="muted">Each scenario starts with your base revenue, then applies its own demand and monthly growth.</p><form id="scenarios-form"><div class="scenario-input-grid">${SCENARIOS.map(s=>`<div class="scenario-input-column"><h3><span class="color-dot" style="background:${s.color}"></span>${s.name}</h3>${numberField('Starting demand multiplier',s.id+'-volume',p.scenarios[s.id].volume,'×',0,10)}${numberField('Monthly revenue growth',s.id+'-growth',p.scenarios[s.id].growth,'%',-100,100)}<p class="field-hint">Month 1 revenue = base revenue × demand.<br>Growth starts in month 2.</p></div>`).join('')}</div><div class="form-footer"><span class="muted">Your assumptions, your perspective.</span><button class="button primary" type="submit">Update scenarios ${icon('arrow')}</button></div></form></section><section class="panel chart-panel"><div class="panel-heading"><h3>A year of possibilities</h3><button class="text-button" data-view="financials">Explore the numbers ${icon('arrow')}</button></div><div class="chart-legend">${SCENARIOS.map(s=>`<span><b style="background:${s.color}"></b>${s.name}</span>`).join('')}</div>${chart(p)}</section>`;}
function versionsView(){const p=active();if(!p)return noPlan();return heading('EVERY STEP IS PART OF THE STORY','Your plan, over time<span class="olive">.</span>','Keep the thinking behind every decision. Revisit any chapter.',`${planSelect()}<button class="button primary" data-action="save-version">${icon('plus')} Save a version</button>`)+`<section class="panel version-current"><span class="stat-icon sage">${icon('edit')}</span><div><h3>Working draft <span class="status">Live</span></h3><p>Last edited ${date(p.updatedAt)} at ${time(p.updatedAt)} · ${progress(p)}% complete</p></div><button class="button" data-action="continue">Continue editing ${icon('arrow')}</button></section><div class="timeline">${p.versions.length?p.versions.slice().reverse().map(v=>`<article class="version-item panel"><span class="timeline-dot">${icon('history')}</span><div class="version-info"><span class="version-number">VERSION ${v.number.toString().padStart(2,'0')}</span><h3>${esc(v.name)}</h3><p>${date(v.createdAt)} at ${time(v.createdAt)} <span>·</span> ${esc(v.author)} <span>·</span> ${progress(v.data)}% complete</p></div><div class="version-actions"><button class="button" data-action="inspect-version" data-id="${v.id}">View snapshot</button><button class="text-button" data-action="restore" data-id="${v.id}">Restore ${icon('history')}</button></div></article>`).join(''):`<div class="empty-state">${icon('history')}<h2>Every idea has a story.</h2><p>Save your first version to capture where you are today.</p><button class="button primary" data-action="save-version">Save your first version</button></div>`}</div>`;}
function settingsView(){return heading('A PLACE TO BUILD TOGETHER','Your workspace<span class="olive">.</span>','Simple tools. Thoughtful collaboration.')+`<div class="settings-grid"><section class="panel settings-card"><div class="panel-heading"><h3>${icon('people')} Your identity</h3></div><p class="muted">This name identifies your plans and saved versions. It is a local profile, not an account or access control.</p><form id="profile-form"><label class="field"><span>Your display name</span><input name="name" value="${esc(user)}" maxlength="60" required></label><button class="button primary" type="submit">Save profile ${icon('check')}</button></form></section><section class="panel settings-card"><div class="panel-heading"><h3>${icon('folder')} Storage & collaboration</h3><span class="status">${source==='files'?'Files connected':'Browser mode'}</span></div><p>${source==='files'?'Your plans are saved as readable JSON files in data/plans/. Every saved version is included in its plan’s file.':'Your plans are saved in this browser. Export each plan to keep a portable backup or share it with your collaborator.'}</p><ol class="steps"><li>Each person creates plans under their own name.</li><li>Run Forma locally to save directly into <code>data/plans/</code>.</li><li>Commit and push your plan files to your private GitHub repository.</li><li>Your partner pulls the changes and refreshes Forma.</li></ol><div class="storage-note">${icon('help')} Git synchronizes files when you push and pull. Forma does not connect to GitHub automatically. Coordinate before editing the same plan.</div><button class="button" data-action="import">${icon('upload')} Import a plan</button><button class="button" data-action="export-all">${icon('download')} Back up workspace</button></section></div><section class="panel settings-card"><h3>A small workspace, without the overhead.</h3><p class="muted">No hosted database is required. JSON keeps plans readable, portable, and easy to review in Git. The hosted preview stores data in your browser; the local app saves files directly. Keep the repository private if it contains confidential business information.</p><button class="text-button" data-action="load-demo">Add example plans ${icon('plus')}</button></section>`;}

function modal(title,body,wide=false){document.querySelector('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><div class="modal-heading"><h2>${title}</h2><button class="icon-button" data-close aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;const root=document.querySelector('#modal-root');root.querySelector('[data-close]').onclick=closeModal;root.querySelector('.modal-overlay').onclick=e=>{if(e.target.classList.contains('modal-overlay'))closeModal();};root.querySelector('input,textarea,select,button:not([data-close])')?.focus();}
function closeModal(){document.querySelector('#modal-root').innerHTML='';}
function createModal(){modal('A new idea, taking shape.',`<p class="muted">Start with the essentials. You can figure out the rest as you go.</p><form id="new-plan-form"><label class="field"><span>Business name</span><input name="title" placeholder="What are you building?" required maxlength="160"></label><label class="field"><span>A little about your idea</span><textarea name="description" placeholder="Your big idea, in a sentence or two." maxlength="400" rows="3"></textarea></label><div class="two-col"><label class="field"><span>Industry</span><select name="industry">${['Lifestyle & retail','Technology','Food & beverage','Consulting & services','Health & wellness','Education','Other'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field"><span>Currency</span><select name="currency"><option value="USD">USD — US Dollar</option><option value="MAD">MAD — Moroccan Dirham</option><option value="EUR">EUR — Euro</option><option value="GBP">GBP — British Pound</option></select></label></div><p class="field-hint">Owned by ${esc(user)}. All three scenarios are included. Sample financial assumptions are editable.</p><div class="modal-footer"><button class="button" type="button" data-cancel>Cancel</button><button class="button primary" type="submit">Create business plan ${icon('arrow')}</button></div></form>`);document.querySelector('[data-cancel]').onclick=closeModal;document.querySelector('#new-plan-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('title').trim())return;const p=newPlan({title:f.get('title').trim(),description:f.get('description').trim(),industry:f.get('industry'),currency:f.get('currency'),owner:user});plans.unshift(p);activeId=p.id;section='summary';view=planView;closeModal();await persist(p);render();toast('A fresh start. Your business plan is ready.');};}
function saveVersionModal(){if(!active())return;modal('Capture this chapter.',`<p class="muted">Save a named snapshot of your plan and all three scenarios.</p><form id="version-form"><label class="field"><span>Version name</span><input name="name" placeholder="e.g. First draft, refined pricing, ready to launch" maxlength="120" required></label><p class="field-hint">Your working draft is autosaved. A version preserves this moment.</p><div class="modal-footer"><button class="button" type="button" data-cancel>Cancel</button><button class="button primary" type="submit">Save version ${icon('check')}</button></div></form>`);document.querySelector('[data-cancel]').onclick=closeModal;document.querySelector('#version-form').onsubmit=async e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;await flush();const p=active();if(p.versions.length>=1000){toast('Version limit reached. Export an archive before starting a new plan.');return;}p.versions.push(snapshot(p,name,user));p.updatedAt=new Date().toISOString();closeModal();await persist(p);render();toast('Version saved. A moment worth keeping.');};}
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importPlan(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{if(input.files[0].size>8e6)throw Error('Please select a file smaller than 8 MB.');const data=JSON.parse(await input.files[0].text());const incoming=(Array.isArray(data)?data:[data]).map(p=>validatePlan(p));if(!incoming.length)throw Error('The file contains no plans.');if(new Set(incoming.map(p=>p.id)).size!==incoming.length)throw Error('The backup contains duplicate plan IDs.');const conflicts=incoming.filter(p=>plans.some(x=>x.id===p.id));const importNow=async()=>{for(const p of incoming){const i=plans.findIndex(x=>x.id===p.id);if(i<0)plans.push(p);else plans[i]=p;await persist(p);}closeModal();activeId=incoming[0].id;view='plans';render();toast(`${incoming.length} plan${incoming.length===1?'':'s'} imported.`);};if(conflicts.length){modal('This plan already has a home.',`<p>Importing will replace ${conflicts.length} existing plan${conflicts.length===1?'':'s'} and their version history. Export a backup first if you want to keep your current work.</p><div class="modal-footer"><button class="button" id="backup-before-import">Back up current workspace</button><button class="button primary" id="confirm-import">Replace and import</button></div>`);document.querySelector('#backup-before-import').onclick=()=>download(plans,'forma-workspace.json');document.querySelector('#confirm-import').onclick=importNow;}else await importNow();}catch(e){toast(e.message||'Could not import this file.');}};input.click();}
function inspectVersion(id){const v=active().versions.find(v=>v.id===id);if(!v)return;modal(esc(v.name),`<div class="snapshot-meta">Version ${v.number} · ${date(v.createdAt)} · ${esc(v.author)}</div>${SECTIONS.map(([key,title])=>`<h3>${title}</h3><p class="snapshot-text">${esc(v.data.sections[key]||'Not written yet.')}</p>`).join('')}${canvasSnapshot(v.data)}<h3>Financial snapshot</h3><div class="table-scroll"><table><thead><tr><th>Scenario</th><th>Revenue</th><th>Profit</th></tr></thead><tbody>${SCENARIOS.map(s=>`<tr><td>${s.name}</td><td>${money(metrics(v.data,s.id).revenue)}</td><td>${money(metrics(v.data,s.id).profit)}</td></tr>`).join('')}</tbody></table></div>`,true);}
function restoreVersion(id){const p=active(),v=p.versions.find(x=>x.id===id);if(!v)return;modal('Revisit an earlier chapter.',`<p>Restore <strong>${esc(v.name)}</strong> as your working draft? We’ll first save your current draft as a safety snapshot, and keep your full version history.</p><div class="modal-footer"><button class="button" id="cancel-restore">Keep editing</button><button class="button primary" id="confirm-restore">Restore version ${icon('history')}</button></div>`);document.querySelector('#cancel-restore').onclick=closeModal;document.querySelector('#confirm-restore').onclick=async()=>{if(p.versions.length>=1000){toast('Version limit reached. Export a backup before restoring.');return;}await flush();const versions=[...p.versions,snapshot(p,'Before restoring '+v.name,user)];const restored={...structuredClone(v.data),versions,updatedAt:new Date().toISOString()};plans[plans.findIndex(x=>x.id===p.id)]=restored;closeModal();await persist(restored);render();toast('Version restored. Your previous draft is safely saved.');};}
function options(id){const p=plans.find(p=>p.id===id);if(!p)return;modal('Plan details',`<form id="details-form"><label class="field"><span>Business name</span><input name="title" value="${esc(p.title)}" required maxlength="160"></label><label class="field"><span>Description</span><textarea name="description" maxlength="400" rows="3">${esc(p.description)}</textarea></label><label class="field"><span>Status</span><select name="status">${['Draft','In progress','Ready to share'].map(x=>`<option ${p.status===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="modal-footer"><button class="button" type="button" id="export-this">${icon('download')} Export plan</button><button class="button primary" type="submit">Save changes ${icon('check')}</button></div></form>`);document.querySelector('#export-this').onclick=()=>download(p,p.id+'.json');document.querySelector('#details-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target);if(!data.get('title').trim())return;p.title=data.get('title').trim();p.description=data.get('description');p.status=data.get('status');p.updatedAt=new Date().toISOString();closeModal();await persist(p);render();};}
function guidance(){modal('A little guidance goes a long way.',`<div class="guide-list"><p><b>01 · Give your idea a home.</b><br>Create a plan, then work through seven practical sections. Your draft saves as you type.</p><p><b>02 · Explore three possibilities.</b><br>Set starting revenue, costs, and cash. Adjust demand and growth for your pessimistic, realistic, and optimistic cases.</p><p><b>03 · Keep the thinking.</b><br>Save a named version at meaningful milestones. View any snapshot, or restore it while preserving your current draft.</p><p><b>04 · Build together.</b><br>Use separate names and plan files. With the local app, commit your JSON files to a private Git repository and pull your collaborator’s changes. In browser mode, export and import plans to exchange them.</p></div><button class="button primary full-width" id="got-it">A clearer plan forward ${icon('arrow')}</button>`);document.querySelector('#got-it').onclick=closeModal;}
function bind(){
  app.querySelectorAll('[data-view]').forEach(b=>b.onclick=async e=>{e.preventDefault();await flush();view=b.dataset.view;if(view==='canvas'||view==='editor'){planView=view;localStorage.setItem('forma-plan-view',view);}render();window.scrollTo(0,0);});
  app.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action;if(a==='new')createModal();else if(a==='continue'){if(!active())return createModal();view=planView;render();}else if(a==='open-plan'){await flush();activeId=b.dataset.id;view=planView;section='summary';render();}else if(a==='plan-options')options(b.dataset.id);else if(a==='save-version')saveVersionModal();else if(a==='export'){if(active())download(active(),active().id+'.json');}else if(a==='export-all')download(plans,'forma-workspace.json');else if(a==='import')importPlan();else if(a==='scenario'){scenario=b.dataset.id;view='scenarios';render();}else if(a==='next-section'){await flush();const index=SECTIONS.findIndex(([id])=>id===section);if(index===SECTIONS.length-1){view='financials';}else section=SECTIONS[index+1][0];render();}else if(a==='inspect-version')inspectVersion(b.dataset.id);else if(a==='restore')restoreVersion(b.dataset.id);else if(a==='expand-canvas'){await flush();canvasExpanded=!canvasExpanded;render();}else if(a==='print-canvas'){await flush();window.print();}else if(a==='guide')guidance();else if(a==='profile'){view='settings';render();document.querySelector('[name="name"]').focus();}else if(a==='menu')document.querySelector('.sidebar').classList.toggle('mobile-open');else if(a==='csv'){const rows=forecast(active(),scenario);download('Month,Revenue,Costs,Operating profit,Cash balance\n'+rows.map(r=>[r.month+1,r.revenue.toFixed(2),r.cost.toFixed(2),r.profit.toFixed(2),r.cash.toFixed(2)].join(',')).join('\n'),active().id+'-'+scenario+'.csv','text/csv');}else if(a==='load-demo'){for(const p of demoPlans()){if(plans.some(x=>x.id===p.id))continue;plans.push(p);await persist(p);}render();toast('Example plans are ready to explore.');}});
  app.querySelectorAll('[data-section]').forEach(b=>b.onclick=async()=>{await flush();section=b.dataset.section;render();});
  app.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{scenario=b.dataset.scenario;render();});
  app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});
  const select=app.querySelector('#plan-select');if(select)select.onchange=async e=>{await flush();activeId=e.target.value;render();};
  const searchInput=app.querySelector('#search');if(searchInput)searchInput.oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();const el=document.querySelector('#search');el.focus();el.setSelectionRange(pos,pos);};
  const text=app.querySelector('#section-text');if(text)text.oninput=e=>{active().sections[section]=e.target.value;document.querySelector('#word-count').textContent=e.target.value.trim().split(/\s+/).filter(Boolean).length+' words';touch();};
  app.querySelectorAll('[data-canvas-block]').forEach(el=>el.oninput=()=>{const p=active();if(!p.canvas)p.canvas=emptyCanvas();p.canvas[el.dataset.canvasBlock]=el.value;growCanvasInput(el);el.closest('.canvas-cell').querySelector('.canvas-cell-print').textContent=el.value;const count=CANVAS_BLOCKS.filter(([id])=>(p.canvas[id]||'').trim()).length;document.querySelector('#canvas-completion').textContent=count+' of 9 blocks started';touch();});
  const af=app.querySelector('#assumptions-form');if(af)af.onsubmit=async e=>{e.preventDefault();af.querySelectorAll('input').forEach(el=>active().assumptions[el.dataset.assumption]=Number(el.value));active().updatedAt=new Date().toISOString();await persist();render();toast('Forecast updated. A fresh perspective.');};
  const sf=app.querySelector('#scenarios-form');if(sf)sf.onsubmit=async e=>{e.preventDefault();sf.querySelectorAll('input').forEach(el=>{const [id,key]=el.dataset.assumption.split('-');active().scenarios[id][key]=Number(el.value);});active().updatedAt=new Date().toISOString();await persist();render();toast('All three scenarios updated.');};
  const pf=app.querySelector('#profile-form');if(pf)pf.onsubmit=e=>{e.preventDefault();const name=new FormData(pf).get('name').trim();if(!name)return;user=name;localStorage.setItem('forma-user',user);render();toast('Profile updated. Welcome, '+user+'.');};
}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'){const m=document.querySelector('.modal');if(!m)return;const els=[...m.querySelectorAll('button,input,select,textarea,a[href]')];const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('beforeunload',()=>{clearTimeout(editingTimer);localStorage.setItem('forma-plans',JSON.stringify(plans));if(source==='files'&&active())fetch('/api/plans/'+active().id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(active()),keepalive:true}).catch(()=>{});});
async function init(){try{const r=await fetch('/api/plans',{signal:AbortSignal.timeout(3000)});if(!r.ok||!r.headers.get('content-type')?.includes('application/json'))throw Error();const data=await r.json();plans=data.map(validatePlan);source='files';}catch{try{const stored=localStorage.getItem('forma-plans');plans=stored?JSON.parse(stored).map(validatePlan):demoPlans();}catch{plans=demoPlans();toast('Could not read browser data. Import a backup to recover your plans.');}}
  plans.sort((a,b)=>Number(b.owner===user)-Number(a.owner===user)||new Date(b.updatedAt)-new Date(a.updatedAt));
  if(!activeId||!plans.some(p=>p.id===activeId))activeId=plans[0]?.id;
  localStorage.setItem('forma-plans',JSON.stringify(plans));render();
}
init();
